insert into public.preferiti (id, dati, salvato_il) values
('as24-19ca2321-e765-48dc-b21a-bb683f31c9e2', '{"anno": 1967, "annuncio_id": "as24-19ca2321-e765-48dc-b21a-bb683f31c9e2", "carrozzeria": "Roadster", "citta": "Arezzo", "fonte": "AutoScout24", "km": 68000, "modello": "MGB", "nota": "", "origine": "annunci", "paese": "IT", "paraurti": "chrome", "prezzo_eur": 16900, "prezzo_salvato": 16900, "punteggio": 80, "salvato_il": "2026-10-30T10:40:19.118Z", "titolo": "MG MGB Roadster 1.8 del 1967 – ASI – guida a sinistra", "url": "https://www.autoscout24.it/annunci/mg-mgb-roadster-1-8-del-1967-asi-guida-a-sinistra-benzina-cat_ma48mo15204-19ca2321-e765-48dc-b21a-bb683f31c9e2", "verdetto": "La più semplice da comprare: già targata in Italia e iscritta ASI, revisione 2025, guida a sinistra, nessuna pratica di importazione. Prima serie con cerchi a raggi, radiatore e alternatore nuovi. Non ha l''overdrive. Il venditore offre un video dell''avviamento a freddo: fattelo mandare e vai a provarla ad Arezzo.", "foto": "assets/foto/as24-19ca2321-e765-48dc-b21a-bb683f31c9e2.webp", "foto_cutout": "assets/cut/as24-19ca2321-e765-48dc-b21a-bb683f31c9e2.webp"}'::jsonb, '2026-10-30T10:40:19.118Z'),
('as24-59ec2229-8734-4ee0-a4be-f3cc1d5a3895', '{"anno": 1973, "annuncio_id": "as24-59ec2229-8734-4ee0-a4be-f3cc1d5a3895", "carrozzeria": "Roadster", "citta": "Wardenburg", "fonte": "AutoScout24", "km": 27000, "modello": "MGB", "nota": "", "origine": "annunci", "paese": "DE", "paraurti": "chrome", "prezzo_eur": 15490, "prezzo_salvato": 15490, "punteggio": 91, "salvato_il": "2026-10-30T10:38:24.688Z", "titolo": "MG MGB Chrom-Modell", "url": "https://www.autoscout24.it/annunci/mg-mgb-chrom-modell-benzina-bianco-cat_ma48mo15204-59ec2229-8734-4ee0-a4be-f3cc1d5a3895", "verdetto": "La migliore oggi. Roadster luglio 1973, restauro completo documentato da foto, dichiarata del tutto senza ruggine con sottoscocca trattato, overdrive funzionante, motore originale, TÜV nuovo senza difetti e targa storica H. Contro: le 27.000 miglia non sono documentate, la data del restauro è ignota e la vernice mostra segni d''uso. Importarla dalla Germania costa circa 1.500–2.500 € tra nazionalizzazione e trasporto, e resta comunque sotto budget. Chiedi foto di sottoporta, longheroni e pianale.", "foto": "assets/foto/as24-59ec2229-8734-4ee0-a4be-f3cc1d5a3895.webp", "foto_cutout": "assets/cut/as24-59ec2229-8734-4ee0-a4be-f3cc1d5a3895.webp"}'::jsonb, '2026-10-30T10:38:24.688Z'),
('u1kap3b3', '{"anno": 1964, "annuncio_id": "as24-d883412f-c5f3-4bb2-9d3a-6a93ce453f89", "carrozzeria": "Roadster", "citta": "Mougins", "fonte": "Car & Classic · AutoScout24", "km": 80175, "modello": "MGB", "nota": "", "origine": "manuale", "paese": "FR", "paraurti": "chrome", "prezzo_eur": 23500, "prezzo_salvato": 23500, "punteggio": 61, "salvato_il": "2026-10-30T10:42:48.695Z", "titolo": "MGB Roadster Mk I ''pull handle'' 1964 – Mougins", "url": "https://www.carandclassic.com/la/C2218749", "url_alternativo": "https://www.autoscout24.it/annunci/mg-mgb-cabriolet-benzina-rosso-cat_ma48mo15204-d883412f-c5f3-4bb2-9d3a-6a93ce453f89", "verdetto": "Prima serie Mk I con maniglie a leva (1962-65), la più ricercata, guida a sinistra, rossa, 80.175 km, venduta da un concessionario a Mougins. A 23.500 € è dentro il budget, ma con trasporto e nazionalizzazione dalla Francia (circa 1.500–2.500 €) arrivi intorno ai 25–26.000 €: prova a trattare. L’annuncio non ha una descrizione, per questo il punteggio automatico è solo 61. Chiedi la storia del restauro, foto di sottoporta e pianale, se ha l’overdrive, se la guida a sinistra è originale (molte MGB del 1964 erano inglesi e sono state convertite) e la carta grigia francese con il contrôle technique.", "foto": "assets/foto/u1kap3b3.webp", "foto_cutout": "assets/cut/u1kap3b3.webp"}'::jsonb, '2026-10-30T10:42:48.695Z'),
('u1ygiogo', '{"anno": 1957, "annuncio_id": null, "carrozzeria": "Roadster", "citta": "", "fonte": "Car & Classic · Autostorico", "km": null, "modello": "MGA", "nota": "", "origine": "manuale", "paese": "GB", "paraurti": "chrome", "prezzo_eur": 35835, "prezzo_salvato": 35835, "punteggio": null, "salvato_il": "2026-10-30T10:39:42.031Z", "titolo": "MGA 1800 Roadster ''Le Mans Special'' 1957", "url": "https://www.carandclassic.com/car/C2017546", "url_alternativo": "https://www.autostorico.co.uk/cars-for-sale/mga-1800-ken-miles-special-evocation", "verdetto": "Prezzo £29.950, circa 35.800 € al cambio di oggi: circa 11.000 € oltre il budget, a cui si aggiungono i costi di importazione dal Regno Unito (IVA ridotta al 10% per le auto storiche, trasporto e nazionalizzazione). Guida a destra. Non è una MGA originale: è un tributo ''Le Mans'' costruito nel 2024 da FW Motors, con riverniciatura a metallo nudo e un motore MGB 1800 da strada veloce (Weber 45 DCOE, cambio a 5 marce, differenziale autobloccante, freni a disco anteriori). Ha un ricco dossier: V5, vecchie revisioni MOT, Heritage Certificate, foto del restauro e fatture. È bellissima e pronta da guidare forte, ma per l''ASI conta che non sia più conforme all''originale: chiedi se il motore e il cambio originali sono inclusi.", "foto": "assets/foto/u1ygiogo.webp", "foto_cutout": "assets/cut/u1ygiogo.webp"}'::jsonb, '2026-10-30T10:39:42.031Z'),
('u1yxkyk8', '{"anno": 1970, "annuncio_id": null, "carrozzeria": "Roadster", "citta": "Monaco", "fonte": "Car & Classic · Garage des Moneghetti (concessionario)", "km": null, "modello": "MGB", "nota": "", "origine": "manuale", "paese": "FR / MC", "paraurti": "chrome", "prezzo_eur": 24500, "prezzo_salvato": 24500, "punteggio": null, "salvato_il": "2026-10-30T10:42:45.540Z", "titolo": "MGB Roadster 1970 blu navy, Weber 45 – Principato di Monaco", "url": "https://www.carandclassic.com/car/C2118636", "verdetto": "24.500 €, dentro il budget ma di poco: con nazionalizzazione e trasporto da Monaco (circa 1.500–2.500 €) sfori di 1.000–2.000 €, quindi tratta. La vende un concessionario, il Garage des Moneghetti, che ha curato l''auto nella sua officina e la fa vedere e provare sul ponte: è un buon segno, approfittane. Pro: voti dichiarati da 6 a 10 su ogni parte, motore al banco a 90 CV, stesso proprietario da 10 anni, nessuna corrosione. Contro: non è originale (Weber 45 al posto dei due SU, cerchi Rostyle a gallettone, gomme a fascia bianca), cosa che può complicare l''iscrizione ASI. Il pianale è già stato rifatto e interni e moquette sono la parte più debole. Al confronto, la 1973 tedesca a 15.490 € offre più originalità per molto meno; questa la paghi per la cura meccanica e per la configurazione. Chiedi se i carburatori SU originali sono inclusi, le foto del rifacimento del pianale e le fatture.", "foto": "assets/foto/u1yxkyk8.webp", "foto_cutout": "assets/cut/u1yxkyk8.webp"}'::jsonb, '2026-10-30T10:42:45.540Z')
